195	    }
196	    for (const key of Object.keys(entry)) {
197	      if (!PACK_ENTRY_KEYS.includes(key)) {
198	        errors.push({ what: `unknown property "${key}" on the "${entry.id}" pack entry`, fix: `remove it or fix the name — valid entry properties: ${PACK_ENTRY_KEYS.join(', ')}` });
199	      }
200	    }
201	    const badShape = (prop, expected) =>
202	      errors.push({ what: `"${prop}" on the "${entry.id}" pack entry must be ${expected}`, fix: `fix or remove the entry's "${prop}"` });
