204	    if (entry.config !== undefined) {
205	      if (entry.config !== null && typeof entry.config === 'object' && !Array.isArray(entry.config)) normalized.config = entry.config;
206	      else badShape('config', 'an object of the pack\'s parameters');
207	    }
208	    if (entry.answers !== undefined) {
209	      if (entry.answers !== null && typeof entry.answers === 'object' && !Array.isArray(entry.answers)
210	        && Object.values(entry.answers).every((v) => typeof v === 'string')) normalized.answers = entry.answers;
211	      else badShape('answers', 'an object mapping the pack\'s question ids to string answers');
212	    }
213	    if (entry.rules !== undefined) {
214	      if (entry.rules !== null && typeof entry.rules === 'object' && !Array.isArray(entry.rules)) normalized.rules = entry.rules;
215	      else badShape('rules', 'an object of per-rule severity overrides');
216	    }
217	    if (entry.accept !== undefined) {
218	      if (Array.isArray(entry.accept)) normalized.accept = entry.accept;
219	      else badShape('accept', 'an array of acceptance entries');
220	    }
221	    if (entry.via !== undefined) {
222	      // Written by the declaration resolver on materialized dependencies
223	      // (engine/pack_loader/pack-registry.mjs) — normalized through so readers (the adoption
224	      // interview) can tell a chosen pack from a pulled-in one.
225	      if (Array.isArray(entry.via) && entry.via.every((v) => typeof v === 'string')) normalized.via = entry.via;
226	      else badShape('via', 'an array of pack ids (the declaration resolver writes it)');
227	    }
228	    packs.push(normalized.id);
229	    packEntries.push(normalized);
230	  }
231	
232	  // --- rules: top-level and per-entry merged; a conflict is a settings error,
233	  // never a silent last-writer-wins — two packs (or a pack and the top level)
234	  // disagreeing about a rule's severity is a decision the project must make.
235	  const rules = {};
236	  const ruleSource = {};
237	  const mergeRules = (overrides, source) => {
238	    for (const [ruleId, severity] of Object.entries(overrides)) {
239	      if (ruleId in rules && rules[ruleId] !== severity) {
240	        errors.push({
241	          what: `rule "${ruleId}" is set to "${rules[ruleId]}" by ${ruleSource[ruleId]} and "${severity}" by ${source}`,
242	          fix: 'make the overrides agree, or keep the rule on one of them',
243	        });
244	        continue;
245	      }
246	      rules[ruleId] = severity;
247	      ruleSource[ruleId] = source;
248	    }
249	  };
250	  if (raw.rules && typeof raw.rules === 'object') mergeRules(raw.rules, 'the top-level "rules"');
251	  for (const entry of packEntries) {
252	    if (entry.rules) mergeRules(entry.rules, `the "${entry.id}" pack entry`);
253	  }
254	
255	  // --- accept: top-level entries, then each pack entry's stamped with its
256	  // provenance (`pack: <id>` — which declaration motivated the exemption).
257	  const accept = Array.isArray(raw.accept) ? [...raw.accept] : [];
258	  for (const entry of packEntries) {
259	    for (const a of entry.accept ?? []) accept.push({ ...a, pack: entry.id });
260	  }
261	
262	  // --- packConfig view: per-pack parameters — e.g. the dirs a repo's
263	  // package.json lives in for the node pack's env install. Entry `config` is
264	  // the home; the legacy top-level key stays readable underneath it.
265	  const packConfig = raw.packConfig && typeof raw.packConfig === 'object' && !Array.isArray(raw.packConfig) ? { ...raw.packConfig } : {};
266	  for (const entry of packEntries) {
267	    if (entry.config !== undefined) packConfig[entry.id] = entry.config;
268	  }
269	
270	  // --- taskScheduler: the per-repo maintenance anchor (UTC). Range-validated at
271	  // load so a bad anchor is a settings error like any other; absence is legal
272	  // (the scheduler fills the documented defaults). The value passes through
273	  // unchanged for the scheduler to normalize.
274	  let taskScheduler = null;
275	  if (raw.taskScheduler !== undefined) {
276	    if (raw.taskScheduler === null || typeof raw.taskScheduler !== 'object' || Array.isArray(raw.taskScheduler)) {
277	      errors.push({ what: '"taskScheduler" must be an object', fix: 'e.g. { "dailyHour": 4, "weeklyDay": "Sun", "monthlyDay": 1 }' });
278	    } else {
279	      for (const key of Object.keys(raw.taskScheduler)) {
280	        if (!SCHEDULE_KEYS.includes(key)) {
281	          errors.push({ what: `unknown "taskScheduler" setting "${key}"`, fix: `remove it or fix the name — valid taskScheduler settings: ${SCHEDULE_KEYS.join(', ')}` });
282	        }
283	      }
284	      const { dailyHour, weeklyDay, monthlyDay } = raw.taskScheduler;
285	      if (dailyHour !== undefined && !(Number.isInteger(dailyHour) && dailyHour >= 0 && dailyHour <= 23)) {
286	        errors.push({ what: `"taskScheduler.dailyHour" must be an integer 0–23 (UTC), got ${JSON.stringify(dailyHour)}`, fix: 'set an hour of the day, 0 through 23' });
287	      }
288	      if (weeklyDay !== undefined && !SCHEDULE_WEEKDAYS.includes(weeklyDay)) {
289	        errors.push({ what: `"taskScheduler.weeklyDay" must be one of ${SCHEDULE_WEEKDAYS.join(', ')}, got ${JSON.stringify(weeklyDay)}`, fix: 'name a weekday, e.g. "Sun"' });
290	      }
291	      if (monthlyDay !== undefined && !(Number.isInteger(monthlyDay) && monthlyDay >= 1 && monthlyDay <= 31)) {
292	        errors.push({ what: `"taskScheduler.monthlyDay" must be an integer 1–31, got ${JSON.stringify(monthlyDay)}`, fix: 'set a day of the month, 1 through 31 (clamped to the month length)' });
293	      }
294	      taskScheduler = raw.taskScheduler;
295	    }
296	  }
297	
298	  // --- dormant: a plain boolean, validated as one. A string "true", a `{ since }`
299	  // object or a reason left in its place would all read as dormant to a truthiness
300	  // test and as active to this one, and the difference is a whole repo's scheduled
301	  // work — so the wrong TYPE is a settings error, not a value to coerce.
302	  if (raw.dormant !== undefined && typeof raw.dormant !== 'boolean') {
303	    errors.push({
304	      what: `"dormant" must be true or false, got ${JSON.stringify(raw.dormant)}`,
305	      fix: 'set "dormant": true to stop this project\'s recurring work, or remove the key',
306	    });
307	  }
308	
309	  return {
310	    packs,
311	    packEntries,
312	    rules,
313	    accept,
314	    sharedConstants: Array.isArray(raw.sharedConstants) ? raw.sharedConstants : [],
315	    packConfig,
316	    taskScheduler,
317	    // Passed through as declared, not normalized: `claudinite` is the
318	    // vendored-mount provenance stamp the `stamp` signal reads, and `maintenance`
319	    // is the delivery preference. Both are in CONFIG_KEYS, so declaring them is
320	    // legal and raises no error — and omitting them from THIS shape is what made
321	    // the stamp invisible to the scheduler and silently killed baselining across
322	    // the whole fleet: every repo self-skipped as "no vendored mount (no stamp)"
323	    // while its scheduler runs went green. A key that validates but does not
324	    // survive the load is the worst kind — legal to write, impossible to read,
325	    // silent in both directions. The CONFIG_KEYS-survive-loadConfig test pins the
326	    // whole set so no future key can go the same way.
327	    claudinite: raw.claudinite ?? null,
328	    maintenance: raw.maintenance ?? null,
329	    // Normalized to a boolean rather than passed through: everything downstream
330	    // asks "is this project dormant", and a tri-state (true / false / absent) would
331	    // invite each caller to answer the absent case for itself. Absent is active.
332	    dormant: isDormant(raw),
333	    errors,
334	  };
335	}
336	
337	export function buildContext({ root, mode = 'changed', baseOverride = null, transcriptPath = null }) {
338	  root = resolve(root);
339	  const baseRef = baseOverride || resolveBaseRef(root);
340	  refreshBaseRef(root, baseRef);
341	  const mergeBase = baseRef ? (gitTry(root, 'merge-base', 'HEAD', baseRef) || '').trim() || null : null;
342	  // Diffing against HEAD keeps uncommitted work in scope even when no base branch resolves.
343	  const diffBase = mergeBase || 'HEAD';
344	  // Is this commit already on the base branch? `--is-ancestor` exits non-zero for "no",
345	  // which gitTry surfaces as null. No base ref to compare against ⇒ nothing is known to
346	  // be on it, so nothing is filtered out.
347	  const onBaseBranch = (sha) =>
348	    !!baseRef && gitTry(root, 'merge-base', '--is-ancestor', sha, baseRef) !== null;
349	
350	  const tracked = lines(gitTry(root, 'ls-files'));
351	  const untracked = lines(gitTry(root, 'ls-files', '--others', '--exclude-standard'));
352	
353	  const vsBase = lines(gitTry(root, 'diff', '--name-only', '--diff-filter=d', diffBase));
354	  let scanned;
355	  if (mode === 'all') {
356	    scanned = [...tracked, ...untracked];
357	  } else {
358	    scanned = [...new Set([...vsBase, ...untracked])];
359	  }
360	  // The vendored corpus under the shared mount is canon-owned, never the
361	  // project's own code — structurally out of scope for every check, on any git
362	  // host and any checkout (deliberately not attribute-driven). The consumer's
363	  // own .claudinite/local_packs/ sits BESIDE the shared mount and stays fully
364	  // in scope.
365	  // git emits '/'-separated paths on every platform; SHARED_SUBDIR is joined
366	  // with the platform separator, so normalize before prefix-matching.
367	  const sharedPrefix = `${SHARED_SUBDIR.split(sep).join('/')}/`;
368	  scanned = scanned.filter((f) => !f.startsWith(sharedPrefix));
369	  // Every in-scope regular file, vendored/generated included.
370	  const allFiles = scanned.filter((f) => existsSync(join(root, f)) && statSync(join(root, f)).isFile());
371	  // The default sweep excludes vendored/generated files, so `ctx.files` is the
372	  // project's OWN authored code and every check skips them for free (see vendoredSet).
373	  const vendored = vendoredSet(root, allFiles);
374	  const files = allFiles.filter((f) => !vendored.has(f));
375	  // The in-scope files the current change touched (vs the scoping base),
376	  // untracked included — the file set behind lines.mjs addedLines, for
377	  // check-the-work rules that judge the work rather than re-audit the world.
378	  const changedSet = new Set([...vsBase, ...untracked]);
379	  const changedFiles = files.filter((f) => changedSet.has(f));
380	
381	  const deleted = mergeBase ? lines(gitTry(root, 'diff', '--name-only', '--diff-filter=D', mergeBase)) : [];
382	
383	  let commits = [];
384	  if (mergeBase) {
385	    const out = gitTry(root, 'log', '--format=%s%n%b%x00', `${mergeBase}..HEAD`);
386	    commits = (out || '').split('\0').map((m) => m.trim()).filter(Boolean);
387	  }
388	
389	  const branch = (gitTry(root, 'rev-parse', '--abbrev-ref', 'HEAD') || '').trim();
390	
391	  // Conversation surface: the Stop hook forwards the session's transcript_path;
392	  // every other surface (CI, a manual run) has none, and conversation rules must
393	  // return [] when this is null. Parsed lazily and cached — most sweeps never ask.
394	  let conversationCache;
395	
396	  // Checks are read-only over an immutable snapshot of the tree, so file and
397	  // base-blob reads are cached for the sweep: many rules re-read the same files,
398	  // and each readBase is otherwise a git subprocess.
399	  const readCache = new Map();
400	  const readBaseCache = new Map();
401	
402	  return {
403	    root,
404	    mode,
405	    baseRef,
406	    mergeBase,
407	    files,
408	    allFiles,
409	    changedFiles,
410	    tracked,
411	    deleted,
412	    commits,
413	    branch,
414	    config: loadConfig(root),
415	
416	    exists: (path) => existsSync(join(root, path)),
417	    read(path) {
418	      if (!readCache.has(path)) {
419	        let text;
420	        try { text = readFileSync(join(root, path), 'utf8'); } catch { text = null; }
421	        readCache.set(path, text);
422	      }
423	      return readCache.get(path);
424	    },
425	
426	    // File content at the scoping base (the merge-base with the base branch), or
427	    // null if the file didn't exist there or no base resolves. Lets a delta
428	    // check compare structured state — e.g. a manifest's permission set — against
429	    // the baseline precisely, immune to text-diff line noise (JSON trailing
430	    // commas make appending an array element re-touch the previous line).
431	    readBase(path) {
432	      if (!mergeBase) return null;
433	      if (!readBaseCache.has(path)) readBaseCache.set(path, gitTry(root, 'show', `${mergeBase}:${path}`));
434	      return readBaseCache.get(path);
435	    },
436	
437	    // Added lines of one file relative to the scoping base (untracked file = every line).
438	    addedLines(file) {
439	      if (!tracked.includes(file)) {
440	        const text = this.read(file);
441	        return text === null ? [] : text.split('\n').map((t, i) => ({ line: i + 1, text: t }));
442	      }
443	      const out = gitTry(root, 'diff', '-U0', diffBase, '--', file);
444	      const added = [];
445	      let lineNo = 0;
446	      for (const l of (out || '').split('\n')) {
447	        const hunk = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@/.exec(l);
448	        if (hunk) { lineNo = Number(hunk[1]); continue; }
449	        if (l.startsWith('+') && !l.startsWith('+++')) { added.push({ line: lineNo, text: l.slice(1) }); lineNo += 1; }
450	        else if (!l.startsWith('-')) lineNo += l ? 1 : 0;
451	      }
452	      return added;
453	    },
454	
455	    // Parsed transcript entries of the session driving this run, or null when no
456	    // transcript is available (see conversationCache above).
457	    conversation() {
458	      if (conversationCache !== undefined) return conversationCache;
459	      if (!transcriptPath || !existsSync(transcriptPath)) return (conversationCache = null);
460	      try { conversationCache = parseEntries(readFileSync(transcriptPath, 'utf8')); }
461	      catch { conversationCache = null; }
462	      return conversationCache;
463	    },
464	
465	    // The branch's own commits since the merge-base, oldest first, each with its
466	    // changed files and committer date — for rules about the ORDER work landed in
467	    // (ctx.commits keeps only messages). Merges excluded: their file list is
468	    // empty under --name-only and their content arrives via their parents.
469	    commitsWithFiles() {
470	      if (!mergeBase) return [];
471	      const out = gitTry(root, 'log', '--reverse', '--no-merges', '--name-only',
472	        '--format=%x00%H%x1f%cI%x1f%s', `${mergeBase}..HEAD`);
473	      const commits = [];
474	      for (const block of (out || '').split('\0')) {
475	        if (!block.trim()) continue;
476	        const [head, ...rest] = block.trim().split('\n');
477	        const [sha, date, subject] = head.split('\x1f');
478	        commits.push({ sha, date, subject, files: rest.map((f) => f.trim()).filter(Boolean) });
479	      }
480	      return commits;
481	    },
482	
483	    // Merge commits the current change introduces — those on HEAD's first-parent
484	    // chain since the merge-base with the base branch (the squash-only effect
485	    // check, scoped to the work). Empty when no base resolves or the branch is
486	    // even with it; pre-existing merges already on the base are out of range.
487	    //
488	    // The range alone trusts the merge-base to be right, and it isn't always: a
489	    // shallow clone's grafted boundary or a criss-cross history can hand back a
490	    // merge-base that sweeps the base branch's own merges into the range. So each
491	    // candidate is confirmed against the base ref itself — a merge already on the
492	    // base branch was never introduced here, whatever the range says. Offline and
493	    // exact, and it holds when refreshBaseRef couldn't run.
494	    introducedMergeCommits() {
495	      if (!mergeBase) return [];
496	      const out = gitTry(root, 'log', '--merges', '--first-parent', '--format=%h %s', `${mergeBase}..HEAD`);
497	      return lines(out).map((l) => {
498	        const i = l.indexOf(' ');
499	        return { sha: l.slice(0, i), subject: l.slice(i + 1) };
500	      }).filter(({ sha }) => !onBaseBranch(sha));
501	    },
502	
503	    // Fixed-string search across tracked files; git grep exits 1 on no match.
504	    // The vendored shared mount is structurally out of the sweep (canon-owned,
505	    // never the project's own code — vendoring/DESIGN.md item 6), so it is
506	    // excluded here exactly as it is from the scanned file set above: a hit
507	    // inside it must never become a finding.
508	    grepTracked(needle) {
509	      const out = gitTry(root, 'grep', '-n', '-F', needle, '--', '.', `:(exclude)${sharedPrefix}`);
510	      return lines(out).map((l) => {
511	        const m = /^([^:]+):(\d+):(.*)$/.exec(l);
512	        return m ? { file: m[1], line: Number(m[2]), text: m[3] } : null;
513	      }).filter(Boolean);
514	    },
515	  };
516	}
517	
518	export const pathDepth = (p) => (p === '.' || p === '' ? [] : p.split(sep));
